package com.dunerealms.bank;
import java.sql.*;import java.lang.reflect.*;import java.math.BigDecimal;import java.util.*;
/** Actual MySQL validation against TEMPORARY tables only. No persistent funds or identities change. */
public final class BankProbe{
 static void ok(boolean value,String reason){if(!value)throw new AssertionError(reason);}
 public static void main(String[] args)throws Exception{String url=System.getenv("MYSQL_TEST_URL"),user=System.getenv("MYSQL_TEST_USER"),pw=System.getenv("MYSQL_TEST_PASSWORD");if(url==null||!url.startsWith("jdbc:mysql:")||user==null||pw==null)throw new IllegalArgumentException("Private MYSQL_TEST environment required");Properties p=new Properties();p.setProperty("user",user);p.setProperty("password",pw);p.setProperty("connectTimeout","3000");p.setProperty("socketTimeout","5000");Class.forName("com.mysql.cj.jdbc.Driver");try(Connection c=DriverManager.getConnection(url,p)){
  Connection ddl=(Connection)Proxy.newProxyInstance(BankProbe.class.getClassLoader(),new Class<?>[]{Connection.class},(a,m,v)->{try{Object value=m.invoke(c,v);if(m.getName().equals("createStatement")){Statement original=(Statement)value;return Proxy.newProxyInstance(BankProbe.class.getClassLoader(),new Class<?>[]{Statement.class},(b,n,w)->{try{if(n.getName().equals("execute")&&w!=null&&w[0] instanceof String sql){ok(sql.startsWith("CREATE TABLE IF NOT EXISTS dune_player_")||sql.startsWith("CREATE TABLE IF NOT EXISTS dune_staff_"),"Known bank DDL only");w[0]=sql.replaceFirst("CREATE TABLE","CREATE TEMPORARY TABLE");}return n.invoke(original,w);}catch(InvocationTargetException e){throw e.getCause();}});}return value;}catch(InvocationTargetException e){throw e.getCause();}});
  BankStore.initialize(ddl);BankStore.initialize(ddl);try(Statement q=c.createStatement()){q.execute("CREATE TEMPORARY TABLE dune_economy_balances(uuid VARCHAR(36) PRIMARY KEY,balance DECIMAL(20,2) NOT NULL)");}UUID player=UUID.fromString("00000000-0000-0000-0009-000000000001");try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_economy_balances VALUES(?,250.25)")){q.setString(1,player.toString());q.executeUpdate();}BankStore store=new BankStore((db,u)->new BankStore.Access(true,true,true));c.setAutoCommit(false);UUID ref=UUID.randomUUID();store.transfer(c,player,false,false,new BigDecimal("100.10"),ref);c.commit();ok(store.wallet(c,player).compareTo(new BigDecimal("150.15"))==0,"wallet cents");ok(store.balance(c,player,false,false).compareTo(new BigDecimal("100.10"))==0,"personal bank cents");
  try{store.transfer(c,player,false,false,new BigDecimal("100.10"),ref);throw new AssertionError("replay accepted");}catch(SQLException expected){c.rollback();}store.transfer(c,player,false,true,new BigDecimal("20.05"),UUID.randomUUID());c.rollback();ok(store.wallet(c,player).compareTo(new BigDecimal("150.15"))==0,"rollback wallet");ok(store.ledger(c,player,false).size()==1,"rollback receipt");
  store.transfer(c,player,true,false,new BigDecimal("50.05"),UUID.randomUUID());c.commit();ok(store.balance(c,player,true,false).compareTo(new BigDecimal("50.05"))==0,"staff balance");try{store.transfer(c,player,true,true,new BigDecimal("50.06"),UUID.randomUUID());throw new AssertionError("overdraft accepted");}catch(SQLException expected){c.rollback();}ok(store.wallet(c,player).compareTo(new BigDecimal("100.10"))==0,"conservation");ok(store.ledger(c,player,true).size()==1,"staff receipt");System.out.println("PASS actual MySQL TEMP-only: personal/staff exact-cents conservation, rollback, replay rejection and overdraft. No persistent rows changed.");
 }}
}
